// Creates a merch with heap-allocated name and description, since ioopm_merch_destroy frees them
static ioopm_merch_t *make_merch(char *name, char *desc, int price)
{
	return ioopm_merch_create(strdup(name), strdup(desc), price);
}

// Adds a new cart to the store with ioopm_cart_add_new and returns it
static ioopm_cart_t *new_cart(ioopm_webstore_t *store)
{
	elem_t found;
	int cart_num = ioopm_cart_add_new(store, string_hash, string_eq);
	ioopm_hash_table_lookup(store->cart_ht, int_elem(cart_num), &found);
	return found.p;
}


