// ---------- cart_add_new ----------

void test_cart_add_new(void)
{
	ioopm_webstore_t store = ioopm_webstore_create(string_hash, string_eq, int_hash, int_eq);
	elem_t found;

	ioopm_cart_add_new(&store, string_hash, string_eq);

	CU_ASSERT_EQUAL(ioopm_hash_table_size(store.cart_ht), 1);
	CU_ASSERT_TRUE_FATAL(ioopm_hash_table_lookup(store.cart_ht, int_elem(1), &found));
	CU_ASSERT_PTR_NOT_NULL_FATAL(found.p);
	CU_ASSERT_TRUE(ioopm_hash_table_is_empty(found.p));

	ioopm_cart_destroy(&store, 1);
	ioopm_merch_destroy_all(&store);
	ioopm_webstore_destroy(&store);
}

void test_cart_add_new_twice_gives_separate_carts(void)
{
	ioopm_webstore_t store = ioopm_webstore_create(string_hash, string_eq, int_hash, int_eq);
	elem_t cart1;
	elem_t cart2;

	ioopm_cart_add_new(&store, string_hash, string_eq);
	ioopm_cart_add_new(&store, string_hash, string_eq);

	CU_ASSERT_EQUAL(ioopm_hash_table_size(store.cart_ht), 2);
	CU_ASSERT_TRUE_FATAL(ioopm_hash_table_lookup(store.cart_ht, int_elem(1), &cart1));
	CU_ASSERT_TRUE_FATAL(ioopm_hash_table_lookup(store.cart_ht, int_elem(2), &cart2));
	CU_ASSERT_PTR_NOT_NULL_FATAL(cart1.p);
	CU_ASSERT_PTR_NOT_NULL_FATAL(cart2.p);
	CU_ASSERT_PTR_NOT_EQUAL(cart1.p, cart2.p);

	ioopm_cart_destroy(&store, 1);
	ioopm_cart_destroy(&store, 2);
	ioopm_merch_destroy_all(&store);
	ioopm_webstore_destroy(&store);
}

