void test_cart_destroy_with_items(void)
{
	ioopm_webstore_t store = ioopm_webstore_create(string_hash, string_eq, int_hash, int_eq);
	ioopm_all_carts_t *cart_ht = store.cart_ht;
	ioopm_cart_t *cart = new_cart(&store);
	CU_ASSERT_PTR_NOT_NULL_FATAL(cart);
	ioopm_merch_t *apple = make_merch("Apple", "Red fruit", 10);
	ioopm_merch_add(&store, apple);
	ioopm_merch_replenish(&store, "Apple", "A25", 10);
	ioopm_cart_add_item(&store, 1, "Apple", 3);

	CU_ASSERT_TRUE(ioopm_cart_destroy(&store, 1));
	CU_ASSERT_TRUE(ioopm_hash_table_is_empty(cart_ht));

	// Removing a cart doesn't change the stock
	CU_ASSERT_EQUAL(ioopm_merch_get_quantity(&store, "Apple"), 10);

	ioopm_merch_destroy_all(&store);
	ioopm_webstore_destroy(&store);
}

